<?php
namespace App\Http\Controllers;
use App\Models\User;use App\Services\{PasswordBridge,SessionBridge,Operations};use Illuminate\Http\Request;use Illuminate\Support\Facades\{Auth,DB,Hash,Password};use Illuminate\Support\Str;
class AdminAuthController extends Controller {
 public function login(Request $r){$data=$r->validate(['email'=>'required|email|max:254','password'=>'required|string|max:256']);$user=User::where('email',strtolower($data['email']))->first();$valid=PasswordBridge::check($data['password'],$user?->password??'$2y$12$OknxLJ7VZfJ5BBf48H3B5uDXhD/3yhQ7qs1.ERzdpmDz8qXHDjaR.');abort_unless($valid&&$user&&$user->role!=='client'&&$user->status==='active',422,'Email or password is incorrect.');
  Auth::guard('web')->login($user);$r->session()->regenerate();$user->forceFill(['last_login_at'=>now()])->save();Operations::log($user,'admin.login','user',$user->id);$bridge=SessionBridge::issue($r,$user);return response()->json(['user'=>$this->user($user),'csrf'=>$bridge['csrf']])->cookie($bridge['cookie']);}
 public function session(Request $r){$user=$r->user();$node=DB::table('sessions')->where('token',$r->session()->get('node_token_hash'))->where('expires','>',(int)(microtime(true)*1000))->first();if(!$node){$bridge=SessionBridge::issue($r,$user);return response()->json(['user'=>$this->user($user),'csrf'=>$bridge['csrf']])->cookie($bridge['cookie']);}return ['user'=>$this->user($user),'csrf'=>$node->csrf];}
 public function logout(Request $r){Operations::log($r->user(),'admin.logout','user',$r->user()->id);SessionBridge::clear($r);Auth::guard('web')->logout();$r->session()->invalidate();$r->session()->regenerateToken();return response()->json(['ok'=>true])->withoutCookie('nb_session');}
 private function user(User $u):array{return ['id'=>$u->id,'name'=>$u->name,'fullName'=>$u->name,'email'=>$u->email,'role'=>$u->role,'permissions'=>$u->capabilities(),'locale'=>$u->locale,'notification_preferences'=>$u->notification_preferences??[]];}
 public function forgot(Request $r){$r->validate(['email'=>'required|email']);abort_unless(config('mail.default')==='smtp'&&config('mail.mailers.smtp.host'),503,'Password reset email delivery is not configured.');$user=User::where('email',$r->email)->where('status','active')->where('role','!=','client')->first();if($user)Password::sendResetLink(['email'=>$user->email]);return ['ok'=>true];}
 public function reset(Request $r){$data=$r->validate(['email'=>'required|email','token'=>'required|string','password'=>'required|confirmed|string|min:12|max:256']);$user=User::where('email',$data['email'])->where('role','!=','client')->first();abort_unless($user,422,'The reset link is invalid or expired.');$result=Password::reset($data,function(User $user,string $password){$user->forceFill(['password'=>Hash::make($password),'remember_token'=>Str::random(60)])->save();DB::table('sessions')->where('user_id',$user->id)->delete();Operations::log($user,'password.reset','user',$user->id);});abort_unless($result===Password::PASSWORD_RESET,422,'The reset link is invalid or expired.');return ['ok'=>true];}
 public function profile(Request $r){$data=$r->validate(['name'=>'sometimes|required|string|max:100','locale'=>'sometimes|in:en,fa','notification_preferences'=>'sometimes|array','notification_preferences.in_app'=>'sometimes|boolean','notification_preferences.email'=>'sometimes|boolean','current_password'=>'required_with:password|string','password'=>'sometimes|required|confirmed|string|min:12|max:256']);$user=$r->user();if(isset($data['password'])){abort_unless(PasswordBridge::check($data['current_password'],$user->password),422,'Current password is incorrect.');$user->password=Hash::make($data['password']);DB::table('sessions')->where('user_id',$user->id)->delete();$r->session()->put('password_hash_web',$user->password);}foreach(['name','locale','notification_preferences'] as $key)if(array_key_exists($key,$data))$user->$key=$data[$key];$user->save();Operations::log($user,'profile.updated','user',$user->id,array_intersect_key($data,array_flip(['name','locale'])));$bridge=SessionBridge::issue($r,$user);return response()->json(['user'=>$this->user($user),'csrf'=>$bridge['csrf']])->cookie($bridge['cookie']);}
}
